    _calcConst: function (q) {
        var qq = q.replace(/[？?。，,，\s]/g, '');
        var mpi = qq.match(/第\s*(\d+)\s*位/);
        var mp2 = qq.match(/第\s*(\d+)\s*个质数/);
        if (mp2) {
            var n = parseInt(mp2[1]);
            if (n >= 1 && n <= 20000) return '第' + n + '个质数是' + this._primeN(n) + '。';
        }
        if (/派|圆周率|π/.test(qq) && (/等于|多少|是|第/.test(qq) || mpi)) {
            if (mpi) {
                var n = parseInt(mpi[1]);
                if (n >= 1 && n <= 5000) return '圆周率π的第' + n + '位小数是' + PI_D.charAt(n + 1);
                return '我记得到第5000位，更大的就超出我的记忆了。';
            }
            return '圆周率π约等于3.14159265358979323846264338327950288419716939937510，我能背到小数点后5000位，你可以问我第几位是多少。';
        }
        if ((/自然常数|欧拉数/.test(qq) || /(^|[^a-z0-9])e([^a-z0-9]|$)/i.test(qq)) && /等于|多少|是|第/.test(qq)) {
            if (mpi) {
                var n2 = parseInt(mpi[1]);
                if (n2 >= 1 && n2 <= 5000) return '自然常数e的第' + n2 + '位小数是' + E_D.charAt(n2 + 1);
                return '我记得到第5000位，更大的就超出我的记忆了。';
            }
            return '自然常数e约等于2.71828182845904523536028747135266249775724709369995，我能背到小数点后5000位，你可以问我第几位是多少。';
        }
        if (/√2|根号2|根号二/.test(qq)) return '√2约等于1.41421356237309504880168872420969807856967187537695，是无理数。';
        if (/√3|根号3|根号三/.test(qq)) return '√3约等于1.73205080756887729352744634150587236694280525381038，是无理数。';
        if (/黄金分割|黄金比例/.test(qq)) return '黄金分割比约等于0.618，用φ表示，φ约等于1.61803398874989484820458683436563811772030917980576。';
        return null;
    },
    _primeN: function (n) {
        if (this._primes && this._primes.length >= n) return this._primes[n - 1];
        var limit = 110000;
        if (n > 20000) limit = 360000;
        var isp = new Array(limit + 1).fill(true);
        isp[0] = isp[1] = false;
        for (var i = 2; i * i <= limit; i++) {
            if (isp[i]) for (var j = i * i; j <= limit; j += i) isp[j] = false;
        }
        var arr = [];
        for (var i = 2; i <= limit && arr.length < n; i++) if (isp[i]) arr.push(i);
        this._primes = arr;
        return arr[n - 1] || 0;
    },
