        if (cm) {
            var n2 = q.split(/(?:乘以|[*乘xX])/).map(function (x) { return parseFloat(x.trim()); });
            var p = 1;
            for (var i = 0; i < n2.length; i++) p *= n2[i];
            p = Math.round(p * 1e8) / 1e8; return q.replace(/\s/g, '') + '=' + p;
        }
