function _bSB(mid, q, a) {
    setTimeout(function () {
        var sb = document.getElementById('sb-' + mid);
        if (!sb) return;
        sb.onclick = function () {
            var i2 = document.getElementById('si-' + mid);
            if (!i2) return;
            var s = parseInt(i2.value);
            if (isNaN(s) || s < 0 || s > 100) { _toast('请输入0-100的分数', 'warn'); return; }
            var el = document.getElementById(mid);
            if (!el) return;
            if (s === 100) {
                el.style.borderLeft = '3px solid #22c55e';
                el.innerHTML = '<b style="color:#22c55e;">评分：' + s + '分 ✅ 满分，答案保留</b>';
                _toast('评分：' + s + '分，满分保留', '');
            } else {
                el.style.borderLeft = '3px solid #f59e0b';
                el.innerHTML = '<b style="color:#f59e0b;">评分：' + s + '分 🔄 AI正在改进答案...</b>';
                _toast('评分：' + s + '分，AI重新生成中', 'warn');
                setTimeout(function () {
                    var na = AI.aFr(q, s);
                    el.innerHTML = 'AI改进：' + _e(na) + '<div style="margin-top:4px"><span>评分</span><input id="si-' + mid + '" type="number" min="0" max="100" style="width:50px" value="" placeholder="分" /><button id="sb-' + mid + '" style="padding:2px 10px;background:#2563eb;color:white;border:none">确定</button></div>';
                    _bSB(mid, q, na);
                    _toast('已根据 ' + s + ' 分生成新答案', '');
                }, 400);
            }
        };
    }, 50);
}

